c['steps']=[step('一幅真正的北宋长卷','张择端画下汴京的街市。我们先看真正的画卷局部：河边有船，桥上有人。这次去北宋看看。','这幅画里的故事在哪个时期？','去北宋，看看桥上桥下。','唐朝更早，这幅作品来自北宋。','听听画里的城市',[D],kind='timeline',options=[era('北宋','960—1127年','cities',True),era('唐朝','618—907年','tang',False)],lead='这是北宋张择端的《清明上河图》。'),step('河流把货物带到城市','画中的汴河是运输的水路。桥下船工忙着过桥，桥上行人和商贩往来。有人运货、有人搬运、有人买卖，城市生活靠不同工作接在一起。','先看看桥下，再看看桥上','找找画里不同的路和工作。','可以再听一遍。','在真画里找一找',[D,N],kind='look-listen',asset=true,display='河里有船。\n桥上有人，街边有买卖。'),step('从真画里找水路和桥','跟小伙伴看看这幅真画：河船走水路，行人可以从桥上过去。先找船，再找过河的桥。','找到在河里运输的船','桥上桥下，各有通行的办法。','再看看河面和桥面。','货到岸边，还要谁帮忙',[D],kind='scene-find',asset=true),step('从船上到街边，还要接一程','这幅新画演一段搬运故事。货物到了岸边，接下来要送进街边。船工和搬运者各有工作，小伙伴该找谁接这一程？','把岸边货物送到街边，找谁？','搬运的人接上这一程，水路和街市连起来。','船工照料河里的船，再找背着货的人。','再回看长卷里的生活',[D,N],options=[card('找背货的搬运者',a,[1040,150,375,370,1536,1024],True),card('找撑船的船工',a,[135,160,325,460,1536,1024],False)],asset=a),step('热闹里，也看见不同生活','长卷让我们看见许多人的工作。画家只画了他选择的场景，不能说明所有人过得一样。看见热闹，也别忘了撑船、搬运和做东西的人。','把人的工作也看进画里','城市的日常，是许多劳动接起来的。','可以再听一遍。','带着城市的发现回家',[D,N],kind='look-listen',asset=true,display='看热闹，也看劳动。\n一幅画，不等于所有人的生活。')]
