c['steps']=[step('宋代编的书，后来人继续保存','《武经总要》在北宋1044年编成。照片是后来明代刻本的封面，时间比编书晚得多。先到北宋，看看这本书为何留下记录。','《武经总要》最初编成在哪一朝？','先到北宋，再看书怎样传下来。','明代刻本在后，最初编书在北宋。','听听为什么把知识写进书',[W,B],kind='timeline',options=[era('北宋','1044年','cities',True),era('明朝','14—17世纪','later',False)],lead='这本书最初在北宋编成。照片是后来留下的明代刻本。'),step('已经有人探索，也有人记下来','火药知识经过长期探索，宋代已经用于军事。曾公亮等人编写《武经总要》，整理当时的知识。书不是发明突然开始的那一天，而是留下记录的一条线索。','古书把当时的知识留下来','前面的探索和后来的记录要分开。','可以再听一遍。','到今天的图书馆找线索',[W,T],kind='look-listen',asset=a,display='先有长期探索。\n北宋编书，记录军事技术。'),step('旧书和今天的笔记，谁留下什么','小伙伴在今天的图书馆看旧书。旁边的人正在做研究笔记：旧书保留以前的文字，今天的笔记记录现在的理解。两种记录不是同一时代。','哪本书是从以前保存下来的？','旧书与今天的研究，各有时间。','再看看展柜与正在书写的地方。','比一比成书与刻印的时间',[W,B],kind='scene-find',asset=a),step('宋代编书，明代又刻印','这本书最初在北宋编成，我们看到的封面却来自明代刻本。小伙伴把两张时间卡排在心里：先有书的内容，后人再刻印流传。','北宋编书和明代刻印，哪个先？','先在北宋编书，后来还有新的刻本。','明代刻印在后，不能改成宋代原纸。','听听一本书的接力',[W,B],options=[era('北宋编成','1044年','cities',True,'calendar'),era('明代刻印','1368—1644年间','later',False,'calendar')],kind='timeline'),step('不同时间的人，把知识接下去','古人探索和记录，后人刻印、保存，今天的人再研究。火药后来也用于不同场合；了解用途，要看对应时代的材料。我们用古书和时间线，认识技术怎样积累。','一项技术，有很长的历史','留下记录，后来的人才能继续认识历史。','可以再听一遍。','带着古书的发现回家',[W,T,B],kind='look-listen',asset=a,display='探索 → 记录 → 刻印保存。\n后来的研究，仍要核对年代。')]
c['steps'][0]['inspection']=ins('wujing-ming-cover','《武经总要》· 后世刻本封面','明代刻本 · 国图藏扫描第1页','这张是真正旧书封面的书影。书的内容在北宋编成，这一本却是明代刻印流传的。圆形水印来自现代馆藏扫描，不是宋代印记。',[B,W],335)
