c=new('cn-ancient-07-06-su-shi-moon','跟苏轼望月，给远方一份祝愿','去听月亮里的祝愿','中秋的月亮很圆，苏轼却和弟弟相隔两地。他把怎样的牵挂，写进《水调歌头》？','1076年中秋，北宋苏轼写《水调歌头》，也思念弟弟苏辙。他借明月寄托祝愿：虽然相隔千里，仍愿亲人平安。','苏轼与弟弟苏辙','《水调歌头》为苏轼词作，主线标明节选，不把诗意当作现场记录。首步为元代赵孟頫1301年所作苏轼像，画中不是作词当夜。两处窗景为文学想象，不标作密州、齐州的真实建筑或苏氏兄弟肖像；三位儿童是今天的读者。',[S,POR,'CCDI-SUSHI-WATER-MELODY'],'相隔很远，也能把牵挂放在同一轮月亮里。')
a='song-moon-wishes-v1'
c['steps']=[step('画里的人，词里的年代','这是后人画的苏轼像。苏轼生活在北宋，1076年中秋写下《水调歌头》，也想到远方的弟弟苏辙。画像是更晚的元代作品。','苏轼写这首词，应该在哪一站？','到北宋，听他写给远方的牵挂。','元代画像更晚，作词的人生活在北宋。','轻轻听这段词',[S,POR],kind='timeline',options=[era('北宋','1076年','cities',True),era('元朝','1301年画像','yuan',False)],lead='苏轼生活在北宋。这张画像是后来的元代作品。'),step('听听《水调歌头》里的祝愿','苏轼在中秋想到远方的弟弟。这是《水调歌头》节选：人有悲欢离合，月有阴晴圆缺，此事古难全。但愿人长久，千里共婵娟。','《水调歌头》· 节选','听到哪一句，就慢慢想一想。','可以再听一遍。','看看词把祝愿托给什么',[S],kind='look-listen',asset=a,display='人有悲欢离合，月有阴晴圆缺，\n此事古难全。\n但愿人长久，千里共婵娟。'),step('词把牵挂托给了什么','人可以写信问候，也可以在词里寄托祝愿。苏轼写“千里共婵娟”，这里的婵娟指明月。小伙伴从这幅想象画里找找。','这句词把远方的祝愿托给什么？','他借明月，表达对远方亲人的牵挂。','信也能问候，这句词借的是明月。','再看看相隔两地的人',[S],options=[card('同一轮明月',a,[750,42,145,148,1536,1024],True),card('桌上的书信',a,[170,374,210,74,1536,1024],False)],asset=a),step('人分在两处，牵挂还能相连','图里两处窗边的人各在一地，下面的小伙伴却站在一起。苏轼想念弟弟时，也是在相隔两地的处境里。看看这幅画怎样表达远方。','哪组人各在一处，却想着彼此？','两处窗景表达相隔，明月寄托牵挂。','小伙伴站在一起，再找两处窗边的人。','把自己的祝愿轻轻说出来',[S],kind='scene-find',asset=a),step('把祝愿带给你牵挂的人','“但愿人长久，千里共婵娟。”希望亲人平安，虽然相隔很远，也能共赏明月。你也可以想一个牵挂的人，说一句自己的祝愿，不用背出整首词。','轻轻望月，想一个牵挂的人','你的祝愿，可以用自己的话说。','可以再听一遍。','带着祝愿回家',[S],kind='look-listen',asset=a,display='但愿人长久，千里共婵娟。\n也给你牵挂的人，一份祝愿。')]
c['steps'][0]['inspection']=ins('su-shi-yuan-portrait-artwork','苏轼像 · 元代赵孟頫绘','1301年后世画像 · 人物是北宋苏轼','这张画画的是苏轼，但画家赵孟頫生活在更晚的元代。画像让后人纪念苏轼，不能当作他写词那一夜的照片。',[POR,S],350)
